<?php
namespace App\Reports\Standard;
use App\Reports\Queries\PurchaseReportQuery;use App\Services\Reports\Contracts\StandardReport;use App\Services\Reports\ReportResult;
final class PurchaseByLocationBusinessUnitReport extends AbstractStandardReport implements StandardReport{
 public function __construct(private readonly PurchaseReportQuery $purchase){}public function code():string{return 'PURCHASE_BY_LOCATION_BU';}public function parameters():array{return array_merge($this->periodParameters(),$this->purchaseFilterParameters());}
 public function run(array $p):ReportResult{$m=PurchaseReportQuery::metricSelects();$rows=$this->purchase->postedInvoiceLines($p)->select('loc.code as location','loc.name as location_name','bu.code as business_unit')->selectRaw('COUNT(DISTINCT p.id) AS invoice_count')->selectRaw('SUM(l.quantity) AS quantity')->selectRaw('SUM('.$m['purchase_amount'].') AS purchase_amount')->selectRaw('SUM('.$m['grand_total'].') AS grand_total')->groupBy('loc.code','loc.name','bu.code')->orderBy('bu.code')->orderBy('loc.code')->get()->all();return new ReportResult('Purchase by Location / Business Unit',[$this->col('business_unit','Business Unit'),$this->col('location','Location'),$this->col('location_name','Location Name'),$this->col('invoice_count','Invoices','number',0),$this->col('quantity','Qty','quantity',4),$this->col('purchase_amount','Purchase','money'),$this->col('grand_total','Total','money')],$rows,['Purchase'=>$this->moneySum($rows,'purchase_amount')],['quantity'=>$this->qtySum($rows,'quantity'),'purchase_amount'=>$this->moneySum($rows,'purchase_amount'),'grand_total'=>$this->moneySum($rows,'grand_total')]);}
}
